 function overlay(result){const svg=$('cameraOverlay');svg.replaceChildren();if(!result)return;svg.setAttribute('viewBox',`0 0 ${result.width} ${result.height}`);const element=(name,attrs)=>{const el=document.createElementNS(NS,name);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;};for(const marker of result.markers)svg.append(element('polygon',{points:marker.corners.map(p=>p.join(',')).join(' '),fill:'#9be66c22',stroke:'#a0eb79','stroke-width':2}));for(const p of result.paths)svg.append(element('path',{d:p.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join(' ')+'Z',fill:'none',stroke:'#f0a370','stroke-width':.85,'vector-effect':'non-scaling-stroke'}));}
