 async function start(){cancelAnalysis();cancelCountdown();frozen=null;lastResult=null;const myEpoch=++epoch;processing=true;$('cameraFrozen').hidden=true;$('liveVideo').hidden=false;overlay(null);status('Waiting for camera access…');$('cameraPlaceholder').hidden=false;$('cameraPlaceholder').textContent='Starting camera…';frameUI();try{const stream=await camera.start({deviceId:$('liveCameraSource').value,width:+$('liveResolution').value});if(!active||myEpoch!==epoch)return;const video=$('liveVideo');video.srcObject=stream;await video.play();if(!active||myEpoch!==epoch)return;await refresh();if(!active||myEpoch!==epoch)return;const s=camera.settings(),caps=camera.capabilities();$('cameraFrameInfo').textContent=`${s.width||video.videoWidth} × ${s.height||video.videoHeight}`;$('cameraPlaceholder').hidden=true;$('cameraOptical').hidden=!caps.zoom&&!caps.torch;$('cameraTorch').hidden=!caps.torch;$('cameraZoom').hidden=$('cameraZoomLabel').hidden=!caps.zoom;if(caps.zoom){const input=$('cameraZoom');input.min=caps.zoom.min;input.max=caps.zoom.max;input.step=caps.zoom.step||.1;input.value=s.zoom||caps.zoom.min;}savePreferences();torch=false;$('cameraTorch').setAttribute('aria-pressed','false');resetWorker();status('Checking calibration squares…');keepAwake();}catch(e){if(active&&myEpoch===epoch){const message=cameraError(e);if(message){camera.stop();status(message,'error');$('cameraPlaceholder').textContent='Camera unavailable';}}}finally{if(active&&myEpoch===epoch){processing=false;frameUI();loop();}}}
