 function scaledImage(image,maxSize){if(Math.max(image.width,image.height)<=maxSize)return {width:image.width,height:image.height,data:new Uint8ClampedArray(image.data)};const source=document.createElement('canvas');source.width=image.width;source.height=image.height;source.getContext('2d').putImageData(image,0,0);const scale=maxSize/Math.max(image.width,image.height),c=document.createElement('canvas');c.width=Math.round(image.width*scale);c.height=Math.round(image.height*scale);const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,c.width,c.height);return ctx.getImageData(0,0,c.width,c.height);}
 async function use(){if(!frozen||processing||!lastResult?.valid)return;const myEpoch=epoch;processing=true;frameUI();status('Correcting perspective and tracing…');try{const result=await (rawReceiver?rawReceiver(frozen):api.useFrame(frozen,()=>active&&myEpoch===epoch));if(!active||myEpoch!==epoch)return;if(result?.ok){closeCamera();return;}status(result?.error||'No usable outline found. Retake with soft light or adjust tracing settings.','error');}catch(e){if(active&&myEpoch===epoch)status(e.message,'error');}finally{if(active&&myEpoch===epoch){processing=false;frameUI();}}}
